(function(){"use strict";
var XHTMLNS = 'http://www.w3.org/1999/xhtml';
function mk(tag){ return document.createElementNS(XHTMLNS, tag); }
var BASE = new URL('./', location.href).pathname;
var useBase = '', chatBase = '', chosenWisp = '', npBase = '';
function testWisp(url){return new Promise(function(resolve){var ws,done=false;var to=setTimeout(function(){if(!done){done=true;try{ws.close();}catch(e){}resolve(false);}},4000);try{ws=new WebSocket(url);ws.onopen=function(){if(!done){done=true;clearTimeout(to);try{ws.close();}catch(e){}resolve(true);}};ws.onerror=function(){if(!done){done=true;clearTimeout(to);resolve(false);}};}catch(e){clearTimeout(to);resolve(false);}});}
async function selectWisp(){try{var r=await fetch(new URL('w.json',location.href),{cache:'no-store'});var list=await r.json();if(Array.isArray(list)){for(var i=0;i<list.length;i++){if(await testWisp(list[i]))return list[i];}}}catch(e){}return (location.protocol==='https:'?'wss://':'ws://')+location.host+'/api/';}
function testBase(base){return new Promise(function(resolve){if(!base){resolve(false);return;}var done=false;var to=setTimeout(function(){if(!done){done=true;resolve(false);}},3500);try{fetch(base.replace(/\/$/,'')+'/w.json',{mode:'no-cors',cache:'no-store'}).then(function(){if(!done){done=true;clearTimeout(to);resolve(true);}}).catch(function(){if(!done){done=true;clearTimeout(to);resolve(false);}});}catch(e){clearTimeout(to);resolve(false);}});}
async function pickBase(list){if(!Array.isArray(list)||!list.length)return '';for(var i=0;i<list.length;i++){try{if(await testBase(list[i]))return list[i];}catch(e){}}return list[0]||'';}
var configReady=(async function(){var uList=null,cList=null,nList=null;try{var b=await (await fetch(new URL('base.json',location.href),{cache:'no-store'})).json();if(b&&Array.isArray(b.use))uList=b.use;if(b&&Array.isArray(b.chat))cList=b.chat;if(b&&Array.isArray(b.np))nList=b.np;if(b&&Array.isArray(b.s)&&b.s.length)sBases=b.s;}catch(e){}var picks=await Promise.all([pickBase(uList||[]),pickBase(cList||[]),pickBase(nList||[]),selectWisp()]);useBase=picks[0]||location.origin;chatBase=picks[1]||location.origin;npBase=picks[2]||location.origin;chosenWisp=picks[3];try{if(typeof zkls!=='undefined')zkls.forEach(function(t){if(t.shortcutsContainer)renderShortcuts(t.shortcutsContainer,t);});}catch(e){}})();

