function showLoad() {
    if (overlayTimer) { clearTimeout(overlayTimer); overlayTimer = null; }
    overlay.classList.add('active');
    overlayTimer = setTimeout(function() { overlay.classList.remove('active'); overlayTimer = null; }, 700);
}

function faviconCandidates(pageUrl) {
    try {
        if (!/^https?:\/\//i.test(pageUrl)) return [];
        var host = new URL(pageUrl).host;
        if (!host) return [];
        var hosts = [host];
        if (host.indexOf('www.') !== 0 && host.split('.').length <= 2) hosts.unshift('www.' + host);
        var out = [];
        ['ico', 'png'].forEach(function (ext) {
            hosts.forEach(function (h) { out.push('https://' + h + '/favicon.' + ext); });
        });
        return out;
    } catch (_) { return []; }
}

function loadFavicon(img, pageUrl, onFail) {
    if (!npBase) { configReady.then(function () { loadFavicon(img, pageUrl, onFail); }); return; }
    var list = faviconCandidates(pageUrl);
    var idx = 0;
    function next() {
        if (idx >= list.length) { img.onerror = null; if (onFail) onFail(); return; }
        img.src = list[idx++];
    }
    img.onerror = next;
    next();
}

function applyFavicon(zkl, url) {
    if (!zkl || !zkl.faviconImg) return;
    var img = zkl.faviconImg;
    if (!faviconCandidates(url).length) { img.style.display = 'none'; return; }
    img.style.display = 'block';
    loadFavicon(img, url, function () { img.style.display = 'none'; });
}

function updateLockIcon(url) {
    var icon = /^http:\/\//i.test(url) ? 'fa-lock-open' : 'fa-lock';
    document.getElementById('p5q6r').innerHTML = '<i class="fa-solid ' + icon + '"></i>';
}

function clearFavicon(zkl) {
    if (!zkl || !zkl.faviconImg) return;
    zkl.faviconImg.src = '';
    zkl.faviconImg.style.display = 'none';
}

var controllerState = { controller: null, initPromise: null, transport: null };

window.zkt = function (n) { try { localStorage.setItem('zkt', n); } catch (e) {} return n; };
async function zkPickTransport(zkw) {
    var pick = null;
    try { pick = localStorage.getItem('zkt'); } catch (e) {}
    var t;
    if (pick === 'rcbkl') {
        t = new (await import(BASE + 'stuff/LyzaHBeO/Oab32X7.js')).Ep082Transport({w: zkw});
    } else {
        t = new window.L1bcTransport.L1bcClient({ww: zkw});
    }
    await t.init();
    return t;
}
async function inits(zkw) {
    await configReady;
    var transportClient = await zkPickTransport(chosenWisp || zkw);

    var swReg = await navigator.serviceWorker.register(BASE + 'static-sw.js', {scope: BASE, updateViaCache: 'none'});
    var activeWorker = swReg.active || await new Promise(function(resolve) {
        var worker = swReg.installing || swReg.waiting;
        worker.addEventListener('statechange', function() {
            if (worker.state === 'activated') resolve(worker);
        });
    });

    var ctrl = new window.$K5qkWTpAController.Controller({
        serviceworker: activeWorker,
        transport: transportClient,
        config: {
            prefix: BASE + 'nZ970vr4/',
            K5qkWTpAPath: BASE + 'stuff/LyzaHBeO/hdr6ZzzC.js',
            injectPath: BASE + 'stuff/LyzaHBeO/jtqxcoHL.js',
            wasmPath: BASE + 'stuff/LyzaHBeO/jCC9IUDB.wasm'
        }
    });
    await ctrl.wait();
    return ctrl;
}

async function ensureController(zkw) {
    if (controllerState.transport === zkw && controllerState.controller) return controllerState.controller;
    if (controllerState.initPromise && controllerState.transport === zkw) return controllerState.initPromise;

    controllerState.transport = zkw;
    controllerState.initPromise = inits(zkw).then(function(ctrl) {
        controllerState.controller = ctrl;
    });

    controllerState.initPromise.catch(function() {
        if (controllerState.transport === zkw) {
            controllerState.controller = null;
            controllerState.initPromise = null;
        }
    });
    return controllerState.initPromise;
}

function revive() {
    if (!navigator.serviceWorker) return;
    navigator.serviceWorker.getRegistrations().then(function (regs) {
        regs.forEach(function (reg) {
            if (reg.active) try { reg.active.postMessage('keepalive'); } catch (e) {}
        });
    }).catch(function () {});
}
setInterval(revive, 15000);

var _SkipVTPlugin = null;
function skipViewTransitionsPlugin() {
    var U = window.$K5qkWTpAUtils;
    if (!U || !U.ManagedPlugin) return null;
    if (!_SkipVTPlugin) {
        _SkipVTPlugin = class extends U.ManagedPlugin {
            constructor() { super('skip-view-transitions', []); }
            install(host) {
                super.install(host);
                this.tap(host.hooks.init.post, function (ctx) {
                    ctx.client.Proxy('Document.prototype.startViewTransition', {
                        apply: function (c) {
                            var t = c.call();
                            if (t && t.skipTransition) t.skipTransition();
                            c.return(t);
                        }
                    });
                });
            }
        };
    }
    try { return new _SkipVTPlugin(); } catch (e) { console.error('skip-view-transitions plugin failed', e); return null; }
}

function buildZklPlugins(zkl) {
    var plugins = [];
    var nw = window.zakaNewWindowPlugin && window.zakaNewWindowPlugin(function (u) {
        try { createZkl(String(u)); } catch (e) { console.error(e); }
    });
    if (nw) plugins.push(nw);
    var U = window.$K5qkWTpAUtils;
    if (!U) return plugins;
    try {
        var svt = skipViewTransitionsPlugin();
        if (svt) plugins.push(svt);
        if (U.HttpCachePlugin) plugins.push(new U.HttpCachePlugin());
        if (U.CatchEscapedLinksPlugin) plugins.push(new U.CatchEscapedLinksPlugin(function (escapedUrl) {
            try { createZkl(String(escapedUrl)); } catch (e) { console.error(e); }
            return new URL('__/escaped.html', location.href).href;
        }));
        if (U.UrlWatcherPlugin) plugins.push(new U.UrlWatcherPlugin(function (realUrl) {
            if (!zkl) return;
            zkl.url = realUrl;
            if (activeZklId !== zkl.id || zkl.isA1) return;
            addrInput.value = realUrl;
            updateLockIcon(realUrl);
            try { zkl.title.textContent = new URL(realUrl).hostname; } catch (e) { zkl.title.textContent = realUrl; }
            applyFavicon(zkl, realUrl);
        }));
    } catch (e) { console.error('plugin setup failed', e); }
    return plugins;
}

function createFrame(zkl) {
    if (zkl.frame && zkl.controller === controllerState.controller) return zkl.frame;
    var frame = controllerState.controller.createFrame(zkl.iframe, { plugins: buildZklPlugins(zkl) });
    if (!frame) throw new Error('createFrame returned null');
    zkl.frame = frame;
    zkl.controller = controllerState.controller;
    return frame;
}

async function navigateFrame(zkl, url, zkw) {
    await ensureController(zkw);
    var frame = createFrame(zkl);
    frame.go(url);
}

function createZkl(startUrl) {
    var id = ++zklCounter;
    var zklEl = mk('div');
    zklEl.className = 'f1g2h';
    zklEl.draggable = true;
    zklEl.dataset.zklId = id;

    var favImg = mk('img');
    favImg.className = 'zkl-favicon';
    favImg.style.display = 'none';
    zklEl.appendChild(favImg);

    var title = mk('span');
    title.className = 'o7p8q';
    title.textContent = startUrl || 'n3w t3b';
    zklEl.appendChild(title);

    var closeBtn = mk('button');
    closeBtn.className = 'r9s0t';
    closeBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
    closeBtn.onclick = function(e) { e.stopPropagation(); closeZkl(id); };
    zklEl.appendChild(closeBtn);
    zklEl.onclick = function() { activateZkl(id); };

    var iframe = mk('iframe');
    iframe.className = 'k9l0m';
    iframe.setAttribute('sandbox', 'allow-same-origin allow-scripts allow-forms allow-modals allow-downloads allow-pointer-lock allow-storage-access-by-user-activation');

    var newZklPage = mk('div');
    newZklPage.className = 'q3r4s';
    var svgNS = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("class", "t5u6v");
    svg.setAttribute("viewBox", "0 0 60 20");
    var rect = document.createElementNS(svgNS, "rect");
    rect.setAttribute("width", "100%"); rect.setAttribute("height", "100%"); rect.setAttribute("fill", "#000"); rect.setAttribute("rx", "4");
    var text = document.createElementNS(svgNS, "text");
    text.setAttribute("x", "50%"); text.setAttribute("y", "55%"); text.setAttribute("fill", "#fff");
    text.setAttribute("font-family", "system-ui,sans-serif"); text.setAttribute("font-size", "12");
    text.setAttribute("font-weight", "600"); text.setAttribute("text-anchor", "middle");
    text.setAttribute("dominant-baseline", "middle"); text.setAttribute("letter-spacing", "0.5");
    text.textContent = "zaka";
    svg.appendChild(rect); svg.appendChild(text);

    var grid = mk('div');
    grid.className = 'w7x8y';
    newZklPage.appendChild(svg);
    newZklPage.appendChild(grid);

    zklBar.insertBefore(zklEl, plusBtn);
    viewRoot.appendChild(iframe);
    viewRoot.appendChild(newZklPage);

    var zkl = { id: id, zkl: zklEl, iframe: iframe, title: title, url: startUrl || '', newZklPage: newZklPage, settingsPage: null, shortcutsContainer: grid, frame: null, zkw: zkwServer, isA1: false, faviconImg: favImg };
    zkls.set(id, zkl);
    renderShortcuts(grid, zkl);
    activateZkl(id);

    if (startUrl) {
        if (startUrl === settingsUrl || startUrl === page50000 || startUrl === page50001 || startUrl === page50002) {
            openSettings(zkl);
        } else {
            navigateZkl(startUrl, id);
        }
    }
    return id;
}

function closeZkl(id) {
    var zkl = zkls.get(id);
    if (!zkl) return;
    var wasActive = activeZklId === id;
    zkl.zkl.remove();
    zkl.iframe.remove();
    if (zkl.newZklPage) zkl.newZklPage.remove();
    if (zkl.settingsPage) zkl.settingsPage.remove();
    zkls.delete(id);
    if (zkls.size === 0) { createZkl(); return; }
    if (wasActive) {
        var keys = Array.from(zkls.keys());
        var idx = keys.indexOf(id);
        activateZkl(keys[Math.max(0, idx - 1)]);
    }
}

function activateZkl(id) {
    var zkl = zkls.get(id);
    if (!zkl) return;
    zkls.forEach(function(t) {
        t.zkl.classList.remove('i3j4k');
        t.iframe.classList.remove('n1o2p');
        if (t.newZklPage) t.newZklPage.style.display = 'none';
        if (t.settingsPage) t.settingsPage.classList.remove('n1o2p');
    });
    zkl.zkl.classList.add('i3j4k');
    activeZklId = id;

    if (zkl.url === settingsUrl || zkl.url === page50000 || zkl.url === page50001 || zkl.url === page50002) {
        openSettings(zkl);
    } else if (zkl.isA1) {
        zkl.iframe.classList.add('n1o2p');
        addrInput.value = a1Url;
        document.getElementById('p5q6r').innerHTML = '<i class="fa-solid fa-lock"></i>';
    } else if (zkl.url) {
        zkl.iframe.classList.add('n1o2p');
        addrInput.value = zkl.url;
        updateLockIcon(zkl.url);
    } else {
        if (zkl.newZklPage) zkl.newZklPage.style.display = 'flex';
        addrInput.value = '';
        document.getElementById('p5q6r').innerHTML = '<i class="fa-solid fa-globe"></i>';
    }
}

function hideNewZkl(zkl) {
    if (zkl.newZklPage) zkl.newZklPage.style.display = 'none';
    zkl.iframe.classList.remove('n1o2p');
    if (zkl.settingsPage) zkl.settingsPage.classList.remove('n1o2p');
}

function showNewZkl(zkl) {
    if (zkl.newZklPage) zkl.newZklPage.style.display = 'flex';
    if (zkl.settingsPage) zkl.settingsPage.classList.remove('n1o2p');
}

function renderShortcuts(container, zkl) {
    container.innerHTML = '';
    shortcuts.forEach(function(s) {
        var t = mk('div');
        t.className = 'z9a0b';
        t.title = zka(s.url);
        var ic = mk('div');
        ic.className = 'c1d2e';
        if (s.img) {
            var iconImg = mk('img');
            iconImg.src = s.img;
            iconImg.alt = zka(s.name);
            ic.appendChild(iconImg);
        } else {
            var icon = mk('i');
            icon.className = s.icon || 'fa-solid fa-globe';
            ic.appendChild(icon);
        }
        var name = mk('div');
        name.className = 'f3g4h';
        name.textContent = zka(s.name);
        t.appendChild(ic); t.appendChild(name);
        t.addEventListener('click', function() {
            if (!zkl) return;
            zkl.url = s.url;
            zkl.title.textContent = s.name;
            hideNewZkl(zkl);
            navigateZkl(s.url, zkl.id);
        });
        container.appendChild(t);
    });
    var dc = mk('a');
    dc.className = 'discord-link';
    dc.href = '#';
    dc.addEventListener('click', function(e) {
        e.preventDefault();
        var u = 'https://discord.gg/33fPjXZPd';
        if (!zkl) return;
        zkl.url = u;
        zkl.title.textContent = 'discord';
        hideNewZkl(zkl);
        navigateZkl(u, zkl.id);
    });
    var dci = mk('img');
    dci.src = BASE + 'img/dc.svg';
    dci.alt = 'discord';
    var dcs = mk('span');
    dcs.textContent = 'join the discord';
    dc.appendChild(dci); dc.appendChild(dcs);
    container.appendChild(dc);
}

function parseInput(input) {
    var val = input.trim();
    if (!val) return null;
    if (/^https?:\/\/\S+$/i.test(val)) return val;
    return searchEngine.replace('%s', encodeURIComponent(val));
}

function navigateZkl(url, zklId) {
    var zkl = zkls.get(zklId);
    if (!zkl) return;
    hideNewZkl(zkl);

    var executeNav = async function() {
        try {
            await navigateFrame(zkl, url, zkwServer);
            zkl.iframe.classList.add('n1o2p');
            if (!zkl.isA1) {
                zkl.url = url;
                addrInput.value = url;
                updateLockIcon(url);
                try { zkl.title.textContent = new URL(url).hostname; } catch(e) { zkl.title.textContent = url; }
                applyFavicon(zkl, url);
            }
        } catch(err) {
            console.error(err);
        }
    };
    executeNav();
}

function openSettings(zkl) {
    if (!zkl.settingsPage) {
        zkl.settingsPage = mk('div');
        zkl.settingsPage.className = 'i5j6k';

        var wrap = mk('div');
        wrap.className = 'l7m8n';

