addrInput.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        var val = addrInput.value.trim();
        var zkl = zkls.get(activeZklId);
        if (!val || !zkl) return;
        showLoad();
        if (val === settingsUrl || val === page50000 || val === page50001 || val === page50002 || val.startsWith('education://')) {
            zkl.url = settingsUrl; zkl.title.textContent = 's3ttin7gs'; openSettings(zkl); return;
        }
        var parsed = parseInput(val);
        if (!parsed) return;
        zkl.url = parsed;
        zkl.title.textContent = parsed.replace(/^https?:\/\//,'').split('/')[0] || val;
        hideNewZkl(zkl);
        navigateZkl(parsed, activeZklId);
    }
});

